//! Copy-paste setup text for connecting coding agents to Opal's MCP server.
//!
//! Pure string building so the Settings page and the tests share one
//! implementation: the page shows whatever these return, and a bad quote here
//! would hand the user a command that silently fails in their shell.

const std = @import("std");

/// `<exe_dir>/opal-mcp` (`.exe` on Windows). Null when it does not fit.
pub fn mcpBinaryPath(buf: []u8, exe_dir: []const u8, windows: bool) ?[]const u8 {
    const sep: []const u8 = if (windows) "\\" else "/";
    const name: []const u8 = if (windows) "opal-mcp.exe" else "opal-mcp";
    return std.fmt.bufPrint(buf, "{s}{s}{s}", .{ exe_dir, sep, name }) catch null;
}

fn needsShellQuote(path: []const u8) bool {
    for (path) |c| {
        if (!(std.ascii.isAlphanumeric(c) or c == '/' or c == '.' or c == '_' or c == '-' or c == '~' or c == ':' or c == '\\')) return true;
    }
    return false;
}

/// `claude mcp add opal -- <path>`; the path is single-quoted when it holds
/// spaces or shell metacharacters. A single quote in the path cannot be quoted
/// portably, so that returns null rather than a command that runs something else.
pub fn claudeCommand(buf: []u8, mcp_path: []const u8) ?[]const u8 {
    if (std.mem.indexOfScalar(u8, mcp_path, '\'') != null) return null;
    if (needsShellQuote(mcp_path)) {
        return std.fmt.bufPrint(buf, "claude mcp add opal -- '{s}'", .{mcp_path}) catch null;
    }
    return std.fmt.bufPrint(buf, "claude mcp add opal -- {s}", .{mcp_path}) catch null;
}

fn writeEscaped(w: *std.Io.Writer, s: []const u8, quote: u8) std.Io.Writer.Error!void {
    for (s) |c| {
        if (c == '\\' or c == quote) try w.writeByte('\\');
        try w.writeByte(c);
    }
}

/// Codex `~/.codex/config.toml` block (TOML basic string).
pub fn codexToml(buf: []u8, mcp_path: []const u8) ?[]const u8 {
    var w = std.Io.Writer.fixed(buf);
    w.writeAll("[mcp_servers.opal]\ncommand = \"") catch return null;
    writeEscaped(&w, mcp_path, '"') catch return null;
    w.writeAll("\"\n") catch return null;
    return w.buffered();
}

/// Generic `mcpServers` JSON for any other client.
pub fn jsonConfig(buf: []u8, mcp_path: []const u8) ?[]const u8 {
    var w = std.Io.Writer.fixed(buf);
    w.writeAll("{\"mcpServers\":{\"opal\":{\"command\":\"") catch return null;
    writeEscaped(&w, mcp_path, '"') catch return null;
    w.writeAll("\"}}}") catch return null;
    return w.buffered();
}

/// `mcpServers` JSON that starts `opal-mcp` with extra arguments (each a plain
/// token, no quotes or backslashes). Used for unattended runs.
pub fn jsonConfigWithArgs(buf: []u8, mcp_path: []const u8, args: []const []const u8) ?[]const u8 {
    var w = std.Io.Writer.fixed(buf);
    w.writeAll("{\"mcpServers\":{\"opal\":{\"command\":\"") catch return null;
    writeEscaped(&w, mcp_path, '"') catch return null;
    w.writeAll("\",\"args\":[") catch return null;
    for (args, 0..) |arg, i| {
        if (std.mem.indexOfAny(u8, arg, "\"\\\n") != null) return null;
        if (i > 0) w.writeAll(",") catch return null;
        w.print("\"{s}\"", .{arg}) catch return null;
    }
    w.writeAll("]}}}") catch return null;
    return w.buffered();
}

/// Where `opal-mcp` appends its audit log.
pub fn auditLogPath(buf: []u8, config_dir: []const u8) ?[]const u8 {
    return std.fmt.bufPrint(buf, "{s}/mcp-audit.jsonl", .{config_dir}) catch null;
}

test "binary path joins per platform" {
    var b: [64]u8 = undefined;
    try std.testing.expectEqualStrings("/opt/opal/opal-mcp", mcpBinaryPath(&b, "/opt/opal", false).?);
    try std.testing.expectEqualStrings("C:\\Opal\\opal-mcp.exe", mcpBinaryPath(&b, "C:\\Opal", true).?);
    var tiny: [4]u8 = undefined;
    try std.testing.expect(mcpBinaryPath(&tiny, "/opt/opal", false) == null);
}

test "claude command quotes unsafe paths and refuses embedded quotes" {
    var b: [128]u8 = undefined;
    try std.testing.expectEqualStrings("claude mcp add opal -- /usr/bin/opal-mcp", claudeCommand(&b, "/usr/bin/opal-mcp").?);
    try std.testing.expectEqualStrings("claude mcp add opal -- '/Users/a b/Opal.app/opal-mcp'", claudeCommand(&b, "/Users/a b/Opal.app/opal-mcp").?);
    try std.testing.expect(claudeCommand(&b, "/tmp/it's/opal-mcp") == null);
    try std.testing.expectEqualStrings("claude mcp add opal -- '/tmp/$(rm)/opal-mcp'", claudeCommand(&b, "/tmp/$(rm)/opal-mcp").?);
}

test "codex and json escape backslashes and quotes" {
    var b: [160]u8 = undefined;
    try std.testing.expectEqualStrings("[mcp_servers.opal]\ncommand = \"/usr/bin/opal-mcp\"\n", codexToml(&b, "/usr/bin/opal-mcp").?);
    try std.testing.expectEqualStrings("[mcp_servers.opal]\ncommand = \"C:\\\\Opal\\\\opal-mcp.exe\"\n", codexToml(&b, "C:\\Opal\\opal-mcp.exe").?);
    try std.testing.expectEqualStrings("{\"mcpServers\":{\"opal\":{\"command\":\"C:\\\\Opal\\\\opal-mcp.exe\"}}}", jsonConfig(&b, "C:\\Opal\\opal-mcp.exe").?);
    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, jsonConfig(&b, "/a \"b\"/opal-mcp").?, .{});
    defer parsed.deinit();
    try std.testing.expectEqualStrings("/a \"b\"/opal-mcp", parsed.value.object.get("mcpServers").?.object.get("opal").?.object.get("command").?.string);
}

test "audit path" {
    var b: [64]u8 = undefined;
    try std.testing.expectEqualStrings("/home/u/.config/opal/mcp-audit.jsonl", auditLogPath(&b, "/home/u/.config/opal").?);
}

test "json config with args lists them and refuses quotes" {
    var b: [256]u8 = undefined;
    try std.testing.expectEqualStrings(
        "{\"mcpServers\":{\"opal\":{\"command\":\"/x/opal-mcp\",\"args\":[\"--deny-prefix\",\"agent_task\"]}}}",
        jsonConfigWithArgs(&b, "/x/opal-mcp", &.{ "--deny-prefix", "agent_task" }).?,
    );
    try std.testing.expect(jsonConfigWithArgs(&b, "/x", &.{"a\"b"}) == null);
}

//! Offline pixels for the Browser hub (Browse > Web): paired browsers, a shared
//! page with detected streams, the first-run state with install guidance and a
//! live pairing code, and a shared page that came without streams. Fixed rows;
//! no database, no listener, no browser.
const std = @import("std");
const dvui = @import("dvui");
const state = @import("../core/state.zig");
const alloc = @import("../core/alloc.zig").allocator;
const workers = @import("../core/workers.zig");
const capture = @import("native_capture.zig");
const link = @import("../services/browser_link.zig");
const shared = @import("../services/browser_page.zig");
const ui = @import("browser_hub.zig");
const theme = @import("theme.zig");

const Case = enum { populated, first_run, no_streams };
var current: Case = .populated;
var links_fixture: [3]link.Link = @splat(.{});
const NOW: i64 = 1_800_000_000;

fn put(dst: []u8, len: *usize, text: []const u8) void {
    const n = @min(text.len, dst.len);
    @memcpy(dst[0..n], text[0..n]);
    len.* = n;
}

fn pageFixture(streams: usize, agents: bool) shared.UiView {
    var v: shared.UiView = .{ .present = true, .page_id = 4, .text_len = 6400, .agents = agents, .shared_at = NOW - 40 };
    put(&v.title, &v.title_len, "Dune: Part Two (2024) - Watch Full Movie Online Free in HD with a title that is far too long for one line of the card");
    put(&v.where, &v.where_len, "https://streams.example.org/watch/dune-part-two-2024/a-long-path-segment/that-keeps-going");
    const kinds = [_]@import("../services/browser_link_pure.zig").Kind{ .hls, .mp4, .dash, .audio, .ts };
    const labels = [_][]const u8{
        "cdn.example.net/hls/dune-part-two/master.m3u8",
        "127.0.0.1:8802/clip.mp4",
        "cdn2.example.net/a/very/long/path/that/should/be/cut/before/it/breaks/the/row/manifest.mpd",
        "media.example.org/audio/track-01.mp3",
        "cdn.example.net/seg-1.ts",
    };
    v.cand_count = streams;
    for (0..streams) |i| {
        v.cands[i] = .{ .id = @intCast(i + 1), .kind = kinds[i], .has_referer = i != 1 };
        put(&v.cands[i].label, &v.cands[i].label_len, labels[i]);
    }
    return v;
}

fn setup() !void {
    state.app.ui_scale = 1;
    state.app.web_remote_enabled = current != .first_run;
    state.app.browser_share_agents = current == .populated;
    for (&links_fixture, 0..) |*row, i| {
        row.* = .{ .id = @intCast(i + 1) };
        const labels = [_][]const u8{ "chrome on Linux x86_64", "firefox on a laptop with a surprisingly long label that is cut", "edge on Windows" };
        const browsers = [_][]const u8{ "chrome", "firefox", "edge" };
        put(&row.label, &row.label_len, labels[i]);
        put(&row.browser, &row.browser_len, browsers[i]);
        row.last_seen = NOW - ([_]i64{ 20, 50 * 60, 3 * 86400 })[i];
    }
    switch (current) {
        .populated => ui.setRenderFixtureForTest(.{ .links = &links_fixture, .page = pageFixture(5, true), .now = NOW }),
        .first_run => ui.setRenderFixtureForTest(.{ .links = links_fixture[0..0], .now = NOW, .pairing = .{ .active = true, .code = "482913".*, .remaining = 97 } }),
        .no_streams => ui.setRenderFixtureForTest(.{ .links = links_fixture[0..1], .page = pageFixture(0, false), .now = NOW }),
    }
}

fn draw() !void {
    var page = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .background = true, .color_fill = theme.colors.bg_app });
    defer page.deinit();
    ui.render();
}

fn cleanup() void {
    ui.setRenderFixtureForTest(null);
}

test "Native browser hub offline SDL pixel capture" {
    const logs = @import("../core/logs.zig");
    logs.logs_allocator = alloc;
    defer logs.deinit();
    workers.init();
    workers.beginShutdownAndDrain(0);
    defer workers.finishShutdown();
    const names = [_][]const u8{ "browser-hub-populated", "browser-hub-first-run", "browser-hub-no-streams" };
    inline for (std.meta.fields(Case), 0..) |f, i| {
        current = @field(Case, f.name);
        for ([_][2]u32{ .{ 1000, 780 }, .{ 640, 780 } }) |size| {
            try capture.capture(size[0], size[1], names[i], setup, draw, cleanup);
        }
    }
}

//! Offline pixels for the Tasks panel on the Agents page: populated list with
//! every outcome tone, the empty state with examples, and the open form with a
//! validation error. Fixed rows; no database, no agent is started.
const std = @import("std");
const dvui = @import("dvui");
const state = @import("../core/state.zig");
const alloc = @import("../core/alloc.zig").allocator;
const workers = @import("../core/workers.zig");
const capture = @import("native_capture.zig");
const tasks = @import("../services/agent_tasks.zig");
const ui = @import("agent_tasks_ui.zig");
const theme = @import("theme.zig");
const io = @import("../core/io_global.zig");

const Case = enum { populated, populated_switch_off, empty, form };
var current: Case = .populated;
var fixture: [5]tasks.Row = @splat(.{});

fn put(dst: []u8, len: *usize, text: []const u8) void {
    @memcpy(dst[0..text.len], text);
    len.* = text.len;
}

fn setup() !void {
    state.app.ui_scale = 1;
    state.app.agent_tasks_enabled = current != .populated_switch_off;
    const now = io.milliTimestamp();
    const names = [_][]const u8{
        "Daily digest",
        "Check wanted list",
        "A task with a very long name that has to stay inside its card without pushing",
        "Finished downloads report",
        "Weekly cleanup (paused)",
    };
    const outcomes = [_][]const u8{ "ok", "running", "failed", "not_installed", "timed_out" };
    const summaries = [_][]const u8{
        "calling tool downloads_list\nNothing is stuck: 4 downloads active, all moving.",
        "",
        "Error: not logged in. Run `claude login` first, then enable the task again so it can retry; this summary is deliberately long enough to be cut by the one-line limit of the panel.",
        "The agent is not installed (not on PATH).",
        "",
    };
    for (&fixture, 0..) |*row, i| {
        row.* = .{
            .id = @intCast(i + 1),
            .agent = if (i == 1 or i == 3) .codex else .claude,
            .enabled = i != 4,
            .running = i == 1,
            .interval_min = ([_]u32{ 1440, 360, 90, 10080, 15 })[i],
            .max_runs_per_day = ([_]u32{ 1, 4, 2, 1, 24 })[i],
            .runs_today = ([_]u32{ 1, 2, 2, 0, 24 })[i],
            .budget_cents = ([_]u32{ 30, 50, 5, 30, 1000 })[i],
            .total_runs = 12,
            .last_run_ms = now - @as(i64, @intCast(i + 1)) * 47 * 60_000,
            .next_run_ms = if (i == 4) 0 else now + @as(i64, @intCast(i + 1)) * 83 * 60_000,
        };
        put(&row.name, &row.name_len, names[i][0..@min(names[i].len, 60)]);
        put(&row.outcome, &row.outcome_len, outcomes[i]);
        put(&row.summary, &row.summary_len, summaries[i]);
    }
    switch (current) {
        .populated, .populated_switch_off => {
            ui.setRenderFixtureForTest(&fixture);
            ui.setFormForTest(false, "");
        },
        .empty => {
            ui.setRenderFixtureForTest(fixture[0..0]);
            ui.setFormForTest(false, "");
        },
        .form => {
            ui.setRenderFixtureForTest(fixture[0..2]);
            ui.setFormForTest(true, "interval_min must be 15 to 10080");
        },
    }
}

fn draw() !void {
    var page = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .background = true, .color_fill = theme.colors.bg_app });
    defer page.deinit();
    {
        // The real toolbar is a horizontal box.
        var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .padding = .{ .x = 10, .y = 6, .w = 10, .h = 6 } });
        defer bar.deinit();
        _ = ui.tabSwitch(2, "Activity");
    }
    ui.render();
}

fn cleanup() void {
    ui.setRenderFixtureForTest(null);
}

test "Native agent tasks offline SDL pixel capture" {
    const logs = @import("../core/logs.zig");
    logs.logs_allocator = alloc;
    defer logs.deinit();
    workers.init();
    workers.beginShutdownAndDrain(0);
    defer workers.finishShutdown();
    const names = [_][]const u8{ "agent-tasks-populated", "agent-tasks-switch-off", "agent-tasks-empty", "agent-tasks-form" };
    inline for (std.meta.fields(Case), 0..) |f, i| {
        current = @field(Case, f.name);
        for ([_][2]u32{ .{ 1100, 900 }, .{ 640, 800 } }) |size| {
            try capture.capture(size[0], size[1], names[i], setup, draw, cleanup);
        }
    }
}

//! Offline pixels for the Overview tab on the Agents page: populated (every
//! automation on, a full activity feed, proposals waiting) and empty (all
//! switches off, nothing happened yet), each at a wide and a narrow window and
//! at the top and bottom of the page. Fixed rows; no database, no agent is
//! started, no network.
//!
//! The Wanted card's text entry is hidden in these captures: the offline capture
//! backend blanks whatever is drawn after a text entry (the Tasks form capture
//! shows the same), so the entry itself is checked in the live app instead.
const std = @import("std");
const dvui = @import("dvui");
const state = @import("../core/state.zig");
const alloc = @import("../core/alloc.zig").allocator;
const workers = @import("../core/workers.zig");
const capture = @import("native_capture.zig");
const wanted = @import("../services/wanted.zig");
const tasks = @import("../services/agent_tasks.zig");
const operator = @import("../services/operator.zig");
const op_pure = @import("../services/operator_pure.zig");
const wanted_pure = @import("../services/wanted_pure.zig");
const tasks_ui = @import("agent_tasks_ui.zig");
const ui = @import("agents_overview.zig");
const theme = @import("theme.zig");
const io = @import("../core/io_global.zig");

const Case = enum { populated, empty };
var current: Case = .populated;
var at_end = false;
var wanted_fx: [6]wanted.Row = @splat(.{});
var tasks_fx: [3]tasks.Row = @splat(.{});
var ops_fx: [6]operator.Row = @splat(.{});

fn put(dst: []u8, len: *usize, text: []const u8) void {
    const n = @min(text.len, dst.len);
    @memcpy(dst[0..n], text[0..n]);
    len.* = n;
}

fn setup() !void {
    state.app.ui_scale = 1;
    const populated = current == .populated;
    state.app.wanted_follow_tv = populated;
    state.app.agent_tasks_enabled = populated;
    state.app.operator_enabled = populated;
    state.app.auto_download_subs = populated;
    state.app.operator_daily_cents = 100;
    const now = io.milliTimestamp();
    const min: i64 = 60_000;

    const titles = [_][]const u8{ "Fixture Movie Alpha", "Fixture Show Beta", "Fixture Movie Gamma With A Rather Long Name Indeed", "Fixture Show Delta", "Fixture Movie Epsilon", "Fixture Show Zeta" };
    const status = [_]wanted_pure.Status{ .wanted, .downloading, .fulfilled, .fulfilled, .wanted, .paused };
    for (&wanted_fx, 0..) |*r, i| {
        r.* = .{
            .id = @intCast(i + 1),
            .kind = if (i % 2 == 1) .episode else .movie,
            .status = status[i],
            .year = if (i % 2 == 0) 2020 + @as(u16, @intCast(i)) else 0,
            .season = 2,
            .episode = @intCast(i + 1),
            .added_ms = now - @as(i64, @intCast(i + 1)) * 300 * min,
            .last_check_ms = now - @as(i64, @intCast(i + 1)) * 41 * min,
        };
        put(&r.title, &r.title_len, titles[i]);
    }

    const task_names = [_][]const u8{ "Daily digest", "Check wanted list", "Weekly cleanup (paused)" };
    const outcomes = [_][]const u8{ "ok", "failed", "" };
    const sums = [_][]const u8{ "Nothing is stuck: 4 downloads active, all moving.", "Error: not logged in. Run `claude login` first, then enable the task again so it can retry.", "" };
    for (&tasks_fx, 0..) |*r, i| {
        r.* = .{
            .id = @intCast(i + 1),
            .enabled = i != 2,
            .interval_min = ([_]u32{ 1440, 360, 10080 })[i],
            .max_runs_per_day = 2,
            .last_run_ms = if (i == 2) 0 else now - @as(i64, @intCast(i + 1)) * 130 * min,
            .next_run_ms = if (i == 2) 0 else now + @as(i64, @intCast(i + 1)) * 83 * min,
        };
        put(&r.name, &r.name_len, task_names[i]);
        put(&r.outcome, &r.outcome_len, outcomes[i]);
        put(&r.summary, &r.summary_len, sums[i]);
    }

    const states = [_]op_pure.State{ .proposed, .applied, .failed, .applied, .queued, .rejected };
    const kinds = [_]op_pure.Kind{ .endpoint_repair, .match_help, .endpoint_repair, .endpoint_repair, .match_help, .endpoint_repair };
    const op_sums = [_][]const u8{
        "Move the source \"Example Index\" from https://old.example to https://new.example (confidence 85%)",
        "Now also searching: Fixture Alt Title, Another Alt",
        "The agent did not finish (not signed in, out of credit, or an error)",
        "Moved a source to https://new-address.example",
        "",
        "",
    };
    for (&ops_fx, 0..) |*r, i| {
        r.* = .{
            .id = @intCast(i + 1),
            .kind = kinds[i],
            .state = states[i],
            .cost_cents = 12,
            .created_ms = now - @as(i64, @intCast(i + 1)) * 67 * min,
            .finished_ms = if (states[i] == .queued or states[i] == .proposed) 0 else now - @as(i64, @intCast(i)) * 59 * min,
        };
        put(&r.key, &r.key_len, "7");
        put(&r.summary, &r.summary_len, op_sums[i]);
        put(&r.agent, &r.agent_len, "claude");
    }

    switch (current) {
        .populated => ui.setRenderFixtureForTest(.{ .wanted = &wanted_fx, .tasks = &tasks_fx, .ops = &ops_fx, .spent = 36, .tracked = 7, .sources = 12, .hide_entry = true }),
        .empty => ui.setRenderFixtureForTest(.{ .hide_entry = true }),
    }
}

fn draw() !void {
    var page = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .background = true, .color_fill = theme.colors.bg_app });
    defer page.deinit();
    {
        var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .padding = .{ .x = 10, .y = 6, .w = 10, .h = 6 } });
        defer bar.deinit();
        _ = tasks_ui.tabSwitch(0, if (current == .populated) "Activity 1" else "Activity");
    }
    if (at_end) ui.scrollToEndForTest();
    ui.render();
}

fn cleanup() void {
    ui.setRenderFixtureForTest(null);
}

test "Native agents overview offline SDL pixel capture" {
    const logs = @import("../core/logs.zig");
    logs.logs_allocator = alloc;
    defer logs.deinit();
    workers.init();
    workers.beginShutdownAndDrain(0);
    defer workers.finishShutdown();
    const names = [_][]const u8{ "agents-overview-populated", "agents-overview-empty" };
    const ends = [_][]const u8{ "-top", "-end" };
    inline for (std.meta.fields(Case), 0..) |f, i| {
        current = @field(Case, f.name);
        for ([_][2]u32{ .{ 1100, 1000 }, .{ 640, 1000 } }) |size| {
            for ([_]bool{ false, true }, 0..) |end, e| {
                at_end = end;
                var name_buf: [64]u8 = undefined;
                const name = try std.fmt.bufPrint(&name_buf, "{s}{s}", .{ names[i], ends[e] });
                try capture.capture(size[0], size[1], name, setup, draw, cleanup);
            }
        }
    }
}

//! Opt-in SDL pixel test. No HTTP, playback, user config, or screen recording.
//! OPAL_GALLERY_ART_DIR may contain tt2543164.jpg, tt1856101.jpg,
//! tt0816692.jpg, tt0245429.jpg. Without it, colored fixture geometry is used.
//! OPAL_GALLERY_CAPTURE_DIR optionally receives rendered PNG artifacts.
const std = @import("std");
const dvui = @import("dvui");
const io = @import("../core/io_global.zig");
const workers = @import("../core/workers.zig");
const alloc = @import("../core/alloc.zig").allocator;
const search = @import("search.zig");
const resolver = @import("resolver.zig");
const content = @import("search_content_pure.zig");

fn field(buffer: []u8, length: *usize, value: []const u8) void {
    length.* = @min(buffer.len, value.len);
    @memcpy(buffer[0..length.*], value[0..length.*]);
}

fn fixtureRows() ![]resolver.ResolvedItem {
    const rows = try alloc.alloc(resolver.ResolvedItem, 14);
    const catalog_ids = [_]i32{ 329865, 335984, 157336, 129 };
    const titles = [_][]const u8{ "Arrival", "Blade Runner 2049", "Interstellar", "Spirited Away", "Fixture album", "Fixture podcast" };
    for (rows, 0..) |*row, index| {
        row.* = .{};
        row.source = if (index < 12) .tmdb else if (index == 12) .music else .podcast;
        row.catalog_id = if (index < 4) catalog_ids[index] else if (index < 12) @intCast(10000 + index) else 0;
